247	/// Serialize the envelope, refusing anything Apple would reject on size.
248	///
249	/// The cap is on the **serialized body**, which is the same quantity the sender's padding
250	/// buckets are defined against — so a body that lands here oversized means the sender's
251	/// arithmetic and this check disagree, which is exactly what `tooLarge` reports.
252	fn serialize_within_cap(body: &serde_json::Value) -> Result<Vec<u8>, ()> {
253	    let bytes = serde_json::to_vec(body).map_err(|_| ())?;
254	    if bytes.len() > MAX_PAYLOAD_BYTES {
255	        return Err(());
256	    }
257	    Ok(bytes)
258	}
